def test_gga_c_wi_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_wi", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.878665839630977e-01, -1.858225675801022e-01, -1.828289453596550e-01, -1.784088039773697e-01, -1.718041222945689e-01, -1.617609679582709e-01, -1.461032632976286e-01, -1.209665097357907e-01, -8.089808132801871e-02, -3.144834539271113e-02, -1.178609410468910e-02, -5.753045656647963e-02, -5.845223755725521e-02, -4.001065159723465e-02, -1.344589056253719e-02, 3.617654857537698e-04, 2.374836318962820e-04, -4.490630145121982e-07, -6.342026733089865e-10, -1.067116938531312e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


